-- Function: public.sp_create_admin_user
-- Backup generated on 2026-11-11 09:05:42

CREATE OR REPLACE PROCEDURE public.sp_create_admin_user(IN p_email character varying, IN p_first_name character varying, IN p_last_name character varying, IN p_password character varying, IN p_role_name character varying, IN p_org_id uuid DEFAULT NULL::uuid)  LANGUAGE plpgsql AS $procedure$ DECLARE     v_user_id uuid;     v_role_id uuid;     v_tenant_id uuid;     v_clean_email character varying;     v_platform_admin_count integer; BEGIN     v_clean_email := lower(trim(p_email));          -- Resolve tenant_id (if org provided, use org tenant_id; else default to primary platform tenant)     IF p_org_id IS NOT NULL THEN         SELECT tenant_id INTO v_tenant_id FROM organizations WHERE id = p_org_id;         IF v_tenant_id IS NULL THEN v_tenant_id := p_org_id; END IF;     END IF;      IF v_tenant_id IS NULL THEN         v_tenant_id := '10000000-0000-0000-0000-000000000001'::uuid;     END IF;      SELECT id INTO v_user_id FROM users WHERE lower(email) = v_clean_email;          IF v_user_id IS NULL THEN         v_user_id := gen_random_uuid();         INSERT INTO users (             id, tenant_id, email, normalized_email, first_name, last_name, display_name,              password_hash, is_active, created_at, updated_at         )         VALUES (             v_user_id,              v_tenant_id,             v_clean_email,              upper(v_clean_email),              p_first_name,              p_last_name,              trim(concat(p_first_name, ' ', p_last_name)),             COALESCE(NULLIF(p_password, ''), 'TEMP_HASH'),             TRUE,              NOW(),              NOW()         );     ELSE         UPDATE users          SET first_name = COALESCE(NULLIF(p_first_name, ''), first_name),             last_name = COALESCE(NULLIF(p_last_name, ''), last_name),             display_name = trim(concat(COALESCE(NULLIF(p_first_name, ''), first_name), ' ', COALESCE(NULLIF(p_last_name, ''), last_name))),             is_active = TRUE,             updated_at = NOW()         WHERE id = v_user_id;     END IF;      IF p_role_name IN ('PlatformAdmin', 'SuperAdmin') THEN         -- Check count of platform administrators (excluding this user if already assigned)         SELECT COUNT(DISTINCT ur.user_id) INTO v_platform_admin_count         FROM user_roles ur         JOIN roles r ON ur.role_id = r.id         WHERE r.name IN ('PlatformAdmin', 'SuperAdmin')           AND ur.user_id != v_user_id;          IF v_platform_admin_count >= 3 THEN             RAISE EXCEPTION 'A maximum of 3 platform administrators can exist at any point in time. Please remove an existing platform administrator before creating a new one.';         END IF;          SELECT id INTO v_role_id FROM roles WHERE name = 'PlatformAdmin' LIMIT 1;         IF v_role_id IS NOT NULL THEN             INSERT INTO user_roles (user_id, role_id)             VALUES (v_user_id, v_role_id)             ON CONFLICT DO NOTHING;         END IF;     ELSE         -- Organization Admin or Organization Owner         SELECT id INTO v_role_id          FROM roles          WHERE name = p_role_name            AND (tenant_id = p_org_id OR tenant_id IS NULL)         ORDER BY tenant_id NULLS LAST          LIMIT 1;          IF p_org_id IS NOT NULL THEN             SELECT tenant_id INTO v_tenant_id FROM organizations WHERE id = p_org_id;             IF v_tenant_id IS NULL THEN v_tenant_id := p_org_id; END IF;              INSERT INTO organization_memberships (user_id, organization_id, tenant_id, status)             VALUES (v_user_id, p_org_id, v_tenant_id, 'Active')             ON CONFLICT (user_id, organization_id) DO UPDATE SET status = 'Active';              IF v_role_id IS NOT NULL THEN                 INSERT INTO user_organization_roles (user_id, role_id, organization_id, tenant_id)                 VALUES (v_user_id, v_role_id, p_org_id, v_tenant_id)                 ON CONFLICT (user_id, role_id, organization_id) DO NOTHING;                  INSERT INTO user_roles (user_id, role_id)                 VALUES (v_user_id, v_role_id)                 ON CONFLICT DO NOTHING;             END IF;         END IF;     END IF; END; $procedure$ ;
